from collections import Counter
import numpy as np

GOLD_PATH = "/root/symb_invariant_consensus/data/folio_full.json"

MODELS = {
    "mistral-7b": {
        "dir": "/root/symb_invariant_consensus/results/exp033_mistral_7b_folio204/intermediates",
    },
    "qwen3-14b-nonthinking": {
        "dir": "/root/symb_invariant_consensus/results/exp027_qwen3_14b_nonthinking/intermediates",
    },
    "qwen3-14b-thinking": {
        "dir": "/root/symb_invariant_consensus/results/exp028b_qwen3_thinking_folio204/intermediates",
    },
}

VALID_ANSWERS = {"True", "False", "Unknown"}

def load_gold():
    with open(GOLD_PATH) as f:
        data = json.load(f)
    return {item["id"]: item["answer"] for item in data}

def normalize_answer(ans):
    if not ans or not ans.strip():
        return None
    a = ans.strip()
    low = a.lower()
    if low in ("true", "yes"):
        return "True"
    if low in ("false", "no"):
        return "False"
    if low in ("unknown", "uncertain", "undetermined"):
        return "Unknown"
    return None

def majority_vote(answers):
    counts = Counter()
    for a in answers:
        if a is not None:
            counts[a] += 1
    if not counts:
        return None
    max_count = max(counts.values())
    for a in answers:
        if a is not None and counts[a] == max_count:
            return a
    return None

def process_model(model_name, model_cfg, gold):
    trace_dir = model_cfg["dir"]
    files = sorted(glob.glob(os.path.join(trace_dir, "folio_*.json")),
                   key=lambda x: int(os.path.basename(x).replace("folio_","").replace(".json","")))

    problem_ids = []
    all_trace_answers = []  # list of lists: [problem_idx][trace_idx] = normalized answer
    n_traces_per_problem = []

    for fpath in files:
        with open(fpath) as f:
            data = json.load(f)
        pid = data["problem"]["id"]
        if pid not in gold:
            continue
        traces = data["sica_result"]["traces"]
        answers = [normalize_answer(t["answer"]) for t in traces]
        problem_ids.append(pid)
        all_trace_answers.append(answers)
        n_traces_per_problem.append(len(traces))

    n_problems = len(problem_ids)
    k = max(n_traces_per_problem) if n_traces_per_problem else 0
    min_k = min(n_traces_per_problem) if n_traces_per_problem else 0

    per_trace_correct = [0] * k
    per_trace_total = [0] * k
    per_problem_agreement = {}
    sc_correct = 0

    for i, pid in enumerate(problem_ids):
        gold_label = gold[pid]
        answers = all_trace_answers[i]
        n_correct_this = 0

        for j, ans in enumerate(answers):
            if j < k:
                per_trace_total[j] += 1
                if ans == gold_label:
                    per_trace_correct[j] += 1
                    n_correct_this += 1

        per_problem_agreement[pid] = {
            "n_correct": n_correct_this,
            "n_total": len(answers),
            "rate": round(n_correct_this / len(answers), 4) if answers else 0,
        }

        mv = majority_vote(answers)
        if mv == gold_label:
            sc_correct += 1

    per_trace_acc = [round(per_trace_correct[j] / per_trace_total[j], 4)
                     if per_trace_total[j] > 0 else 0.0 for j in range(k)]
    single_mean = round(float(np.mean(per_trace_acc)), 4)
    single_std = round(float(np.std(per_trace_acc)), 4)
    sc12_acc = round(sc_correct / n_problems, 4) if n_problems > 0 else 0
    agg_gain = round((sc12_acc - single_mean) * 100, 2)

    rates = [v["rate"] for v in per_problem_agreement.values()]
    rates_arr = np.array(rates)
    agreement_stats = {
        "mean": round(float(np.mean(rates_arr)), 4),
        "median": round(float(np.median(rates_arr)), 4),
        "q1": round(float(np.percentile(rates_arr, 25)), 4),
        "q3": round(float(np.percentile(rates_arr, 75)), 4),
    }

    print(f"\n=== {model_name} ===")
    print(f"  n_problems: {n_problems}, k: {min_k}-{k}")
    print(f"  single_trace_mean: {single_mean} ± {single_std}")
    print(f"  per_trace_acc: {per_trace_acc}")
    print(f"  SC@{k}: {sc12_acc} ({sc_correct}/{n_problems})")
    print(f"  aggregation_gain: {agg_gain} pp")
    print(f"  agreement stats: {agreement_stats}")

    return {
        "n_problems": n_problems,
        "n_traces": k,
        "n_traces_range": f"{min_k}-{k}" if min_k != k else str(k),
        "single_trace_mean": single_mean,
        "single_trace_std": single_std,
        "single_trace_per_k": per_trace_acc,
        "sc12_accuracy": sc12_acc,
        "sc12_correct": sc_correct,
        "aggregation_gain_pp": agg_gain,
        "agreement_stats": agreement_stats,
    }, per_problem_agreement

def main():
    gold = load_gold()
    print(f"Loaded {len(gold)} gold labels")

    result = {"models": {}, "per_problem_agreement": {}}

    for model_name, model_cfg in MODELS.items():
        model_result, per_problem = process_model(model_name, model_cfg, gold)
        result["models"][model_name] = model_result
        result["per_problem_agreement"][model_name] = per_problem

    out_path = "/root/symb_invariant_consensus/results/dir_l_single_trace/results.json"
    with open(out_path, "w") as f:
        json.dump(result, f, indent=2)
    print(f"\nResults written to {out_path}")

if __name__ == "__main__":
    main()
