def load_gold():
    with open(GOLD_PATH) as f:
        data = json.load(f)
    return {item["id"]: item["answer"] for item in data}

def normalize_answer(ans):
    if not ans or not ans.strip():
        return None
    low = ans.strip().lower()
    if low in ("true", "yes"):
        return "True"
    if low in ("false", "no"):
        return "False"
    if low in ("unknown", "uncertain", "undetermined"):
        return "Unknown"
    return None

def majority_vote(answers):
    counts = Counter()
    for a in answers:
        if a is not None:
            counts[a] += 1
    if not counts:
        return None
    max_count = max(counts.values())
    for a in answers:
        if a is not None and counts[a] == max_count:
            return a
    return None

def process_model(model_name, model_cfg, gold):
    trace_dir = model_cfg["dir"]
    extra = model_cfg["extra"]

    files = sorted(
        glob.glob(os.path.join(trace_dir, "folio_*.json")),
        key=lambda x: int(os.path.basename(x).replace("folio_", "").replace(".json", ""))
    )

    # pid -> list of normalized answers (len=K)
    pid_answers = {}
    for fpath in files:
        with open(fpath) as f:
            data = json.load(f)
        pid = data["problem"]["id"]
        if pid not in gold:
            continue
        traces = data["sica_result"]["traces"]
        answers = [normalize_answer(t["answer"]) for t in traces]
        pid_answers[pid] = answers

