        answers = pid_answers[pid]
        for j, ans in enumerate(answers):
            if ans == gold_label:
                per_trace_correct[j] += 1
        mv = majority_vote(answers)
        if mv == gold_label:
            sc_correct += 1

    per_trace_acc = [round(per_trace_correct[j] / n_problems, 6) for j in range(k)]
