    agg_gain = round((sc_acc - single_mean) * 100, 2)

    print(f"\n=== {model_name} ===")
    print(f"  n_questions: {n_problems}, k: {k}")
    print(f"  per_trace_acc: {per_trace_acc}")
    print(f"  single_trace_mean: {single_mean} +/- {single_std}")
